package com.eugenia.orders.domain;
import java.math.BigDecimal; import java.util.*;
public final class OrderValidator { public record Input(String eventId,int eventVersion,String orderId,Market market,String currency,String clientId,List<InputItem> items){} public record InputItem(String productId,int quantity,BigDecimal unitPrice){} public void validate(Input x){if(x==null||blank(x.eventId())||blank(x.orderId())||blank(x.clientId())||x.market()==null)throw new IllegalArgumentException("required fields missing"); if(!x.market().currency().equals(x.currency()))throw new IllegalArgumentException("currency does not match market"); if(x.eventVersion()<1||x.items()==null||x.items().isEmpty())throw new IllegalArgumentException("invalid version or items"); var ids=new HashSet<String>(); for(var i:x.items()){if(i==null||blank(i.productId())||i.quantity()<=0||i.unitPrice()==null||i.unitPrice().signum()<0)throw new IllegalArgumentException("invalid item"); if(!ids.add(i.productId()))throw new IllegalArgumentException("duplicate productId");}} private boolean blank(String v){return v==null||v.isBlank();} }
